#!/usr/bin/env python3
"""Bruteforce Firefox profile merge: merge all source profiles into the target.

Usage: ff_profile_merge.py [--dry-run] [--target DIR] [source1 source2 ...]
"""
import sqlite3, os, shutil, json, sys, glob as globmod

FIREFOX_DIR = os.path.expanduser("~/.mozilla/firefox")

# Known SQLite files to merge (table-level dedup)
SQLITE_MERGE = {
    "places.sqlite": [
        ("moz_places", "id", ["url", "title", "rev_count", "frecency", "last_visit_date", "visit_count", "hidden", "typed"]),
        ("moz_historyvisits", "id", ["from_visit", "place_id", "visit_date", "visit_type", "session"]),
        ("moz_bookmarks", "id", ["type", "parent", "position", "title", "keyword_id", "folder_type", "dateAdded", "lastModified"]),
        ("moz_bookmarks_roots", "folder_id", []),
        ("moz_annos", "id", ["annoval", "item_id", "item_type", "mime_type", "flags", "dateAdded", "lastModified"]),
        ("moz_favicons", "id", ["url", "width", "height", "data", "last_modified"]),
        ("moz_pages_favicons", "page_id", []),
    ],
    "cookies.sqlite": [
        ("moz_cookies", "id", ["host", "name", "value", "path", "expiry", "lastAccessed", "creationTime", "isSecure", "isHttpOnly", "samesite", "scheme"]),
    ],
    "logins.db": [
        ("moz_logins", "guid", ["hostname", "httpRealm", "username", "password", "formSubmitURL", "timeCreated", "timeLastUsed", "timePasswordChanged"]),
        ("moz_disvocales", "id", []),
    ],
    "favicons.sqlite": [
        ("moz_favicons", "id", ["url", "width", "height", "data", "last_modified"]),
        ("moz_pages_favicons", "page_id", []),
    ],
    "permissions.sqlite": [
        ("moz_permissions", "id", ["origin", "type", "state", "timeStamp"]),
    ],
    "formhistory.sqlite": [
        ("moz_formhistory", "id", ["name", "value", "firstUsed", "lastUsed", "useCount"]),
        ("moz_formhistory_origin", "guid", []),
    ],
}

# Files to copy directly (non-SQLite)
FILE_COPY = [
    "extensions.json",
    "extension-settings.json",
    "addonStartup.json.lz4",
    "cookies.sqlite-wal", "cookies.sqlite-shm",
    "places.sqlite-wal", "places.sqlite-shm",
    "logins.json",
    "key4.db",
    "signons.sqlite", "signons.sqlite-wal", "signons.sqlite-shm",
    "favicons.sqlite-wal", "favicons.sqlite-shm",
    "permissions.sqlite-wal", "permissions.sqlite-shm",
    "formhistory.sqlite-wal", "formhistory.sqlite-shm",
    "sessionstore.jsonlz4",
    "sessionCheckpoints.json",
    "Telemetry.ShutdownTime.txt",
    "SiteSecurityServiceState.bin",
    "AlternateServices.bin",
    "storage.sqlite",
    "storage.sqlite-wal", "storage.sqlite-shm",
    "suggest.sqlite", "suggest.sqlite-wal", "suggest.sqlite-shm",
    "places_semantic.sqlite", "places_semantic.sqlite-wal", "places_semantic.sqlite-shm",
    "bounce-tracking-protection.sqlite",
    "synced-tabs.db", "synced-tabs.db-wal", "synced-tabs.db-shm",
    "favicons.sqlite",
    "times.json",
]

def merge_sqlite(src_path, dst_path, dry_run=False):
    """Merge all known tables from src into dst with dedup."""
    if not os.path.exists(src_path):
        return {"file": src_path, "status": "missing"}
    if not os.path.exists(dst_path):
        # Copy entire file if dst doesn't exist
        if dry_run:
            return {"file": src_path, "status": "would_create"}
        shutil.copy2(src_path, dst_path)
        return {"file": src_path, "status": "created"}

    result = {"file": os.path.basename(src_path), "status": "ok", "tables": {}}
    src = sqlite3.connect(f"file:{src_path}?mode=ro", uri=True)
    dst = sqlite3.connect(f"file:{dst_path}?mode=rw", uri=True)

    for table, pk_col, _ in SQLITE_MERGE.get(os.path.basename(src_path), []):
        try:
            src_cols = [r[1] for r in src.execute(f"PRAGMA table_info({table})").fetchall()]
            if not src_cols:
                continue
            # Get existing PKs in dst
            try:
                existing = set(r[0] for r in dst.execute(f"SELECT {pk_col} FROM {table}").fetchall())
            except sqlite3.OperationalError:
                existing = set()

            placeholders = ",".join("?" * len(src_cols))
            col_list = ",".join(src_cols)
            inserted = 0
            for row in src.execute(f"SELECT {col_list} FROM {table}").fetchall():
                pk = row[src_cols.index(pk_col)] if pk_col in src_cols else None
                if pk is not None and pk in existing:
                    continue
                if dry_run:
                    inserted += 1
                    continue
                try:
                    dst.execute(f"INSERT OR IGNORE INTO {table} ({col_list}) VALUES ({placeholders})", row)
                    if dst.changes() > 0:
                        inserted += 1
                except sqlite3.IntegrityError:
                    pass
            dst.commit()
            result["tables"][table] = inserted
        except sqlite3.OperationalError as e:
            result["tables"][table] = f"error: {e}"

    src.close()
    dst.close()
    return result

def copy_file(src, dst, dry_run=False):
    if not os.path.exists(src):
        return {"file": src, "status": "missing"}
    if dry_run:
        return {"file": src, "status": "would_copy"}
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    shutil.copy2(src, dst)
    return {"file": src, "status": "copied"}

