                   "favicons.sqlite","times.json"]:
            sp = os.path.join(src, f)
            if os.path.exists(sp): sr[f] = copy_file(sp, os.path.join(TARGET, f), dry)
        for d in ["storage","sessionstore-backups","bookmarkbackups","saved-telemetry-pings",
                   "datareporting","sessionstore-logs","extensions","extension-store-menus",
