FIREFOX = os.path.expanduser("~/.mozilla/firefox")
TARGET = os.path.join(FIREFOX, "7c8v85fg.default-nightly")
SOURCES = ["g304xzha.default-release", "mrbziu3z.default"]

def get_tables(db_path):
    """Get all tables and their PKs from a SQLite DB."""
    if not os.path.exists(db_path):
        return {}
    try:
        conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
        tables = {}
        for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE 'moz_%'").fetchall():
            pass  # we want ALL tables
        for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").fetchall():
            tname = row[0]
            cols = [c[1] for c in conn.execute(f"PRAGMA table_info({tname})").fetchall()]
            pk = None
            for c in conn.execute(f"PRAGMA table_info({tname})").fetchall():
                if c[5]:  # pk column
                    pk = c[1]
                    break
            if not pk and cols:
                pk = cols[0]
            tables[tname] = {"cols": cols, "pk": pk}
        conn.close()
        return tables
    except Exception as e:
        return {"error": str(e)}

def merge_sqlite(src, dst, dry=False):
    """Merge all tables from src SQLite into dst, dedup by PK."""
    if not os.path.exists(src):
        return {"status": "missing"}
    if not os.path.exists(dst):
        if dry:
            return {"status": "would_create"}
        shutil.copy2(src, dst)
        return {"status": "created"}

    r = {"status": "ok", "tables": {}}
    s = sqlite3.connect(f"file:{src}?mode=ro", uri=True)
    d = sqlite3.connect(f"file:{dst}?mode=rw", uri=True)

    fname = os.path.basename(src)
    src_tables = get_tables(src)

    for tname, info in src_tables.items():
        if "error" in info:
            r["tables"][tname] = f"err:{info['error']}"
            continue
        cols = info["cols"]
        pk = info["pk"]
        if not cols:
            continue
        try:
            # Check if table exists in dst
            dst_tables = get_tables(dst)
            if tname not in dst_tables:
                # Create table in dst
                col_defs = ", ".join([f'"{c}"' for c in cols])
                d.execute(f"CREATE TABLE IF NOT EXISTS {tname} ({col_defs})")
                d.commit()

            # Get existing PKs
            try:
                existing = set(row[0] for row in d.execute(f"SELECT "{pk}" FROM {tname}").fetchall())
            except:
                existing = set()

            ph = ",".join("?" * len(cols))
            cl = ",".join([f'"{c}"' for c in cols])
            n = 0
            for row in s.execute(f'SELECT "{cl}" FROM {tname}').fetchall():
                if dry:
                    n += 1
                    continue
                try:
                    d.execute(f'INSERT OR IGNORE INTO {tname} ({cl}) VALUES ({ph})', row)
                    if d.changes() > 0:
                        n += 1
                except:
                    pass
            d.commit()
            r["tables"][tname] = n
        except Exception as e:
            r["tables"][tname] = f"err:{e}"

    s.close()
    d.close()
    return r

def copy_file(src, dst, dry=False):
    if not os.path.exists(src):
        return {"status": "missing"}
    if dry:
        return {"status": "would_copy"}
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    shutil.copy2(src, dst)
    return {"status": "copied"}

def merge_dir(src, dst, dry=False):
    if not os.path.exists(src):
        return {"status": "missing"}
    r = {"status": "ok", "files": 0}
    for root, dirs, files in os.walk(src):
        rel = os.path.relpath(root, src)
        d = os.path.join(dst, rel) if rel != "." else dst
        for f in files:
            s = os.path.join(root, f)
            if dry:
                r["files"] += 1
                continue
            os.makedirs(d, exist_ok=True)
            shutil.copy2(s, os.path.join(d, f))
            r["files"] += 1
    return r

def main():
    dry = "--dry-run" in sys.argv
    results = {}

    for src_name in SOURCES:
        src = os.path.join(FIREFOX, src_name)
        if not os.path.exists(src):
            results[src_name] = {"status": "missing"}
            continue

        sr = {}

        # SQLite files - merge at table level
        for f in os.listdir(src):
            if f.endswith(".sqlite") or f.endswith(".db"):
                sp = os.path.join(src, f)
                if os.path.isfile(sp):
                    sr[f] = merge_sqlite(sp, os.path.join(TARGET, f), dry)

        # Copy non-SQLite files
        skip_dirs = {"storage", "saved-telemetry-pings", "datareporting",
                     "sessionstore-logs", "extensions", "extension-store-menus",
                     "security_state", "crash-logs", "crash-reports",
                     "sessionstore-backups", "bookmarkbackups"}
        for f in os.listdir(src):
            sp = os.path.join(src, f)
            if os.path.isfile(sp) and f not in sr:
                sr[f] = copy_file(sp, os.path.join(TARGET, f), dry)

        # Merge directories
        for d in skip_dirs:
            dp = os.path.join(src, d)
            if os.path.isdir(dp):
                sr[d] = merge_dir(dp, os.path.join(TARGET, d), dry)

        results[src_name] = sr

    print(json.dumps(results, indent=2, default=str))

if __name__ == "__main__":
    main()"}

